# r591 bm-b S0 integration (r585 pure-FF + split checkout + r589 re-land law)
# Facts: merge-base==HEAD, origin +1 (bm-a r590 695a88506).
# Origin regressed MY 4 identity faces (stale-carry in bm-a surgical payload):
#   state.json (r590->589), fleet/machines/bm-b.json (hb 19:34->19:19),
#   logs/iteration-loop/round_reports.md (r590 line dropped), seat MSG inbox copy.
# pool_core_samples.jsonl: local dirty = uncommitted W111 burn-tail samples;
#   origin has bm-a W112 appends -> UNION REQUIRED (r570/r580 law).
# Dirty-cap-delta shared-derive faces: take origin (L1 re-derive, regenerated by S6).
import json, subprocess, sys

def run(args, **kw):
    r = subprocess.run(args, capture_output=True, **kw)
    return r.returncode, r.stdout, r.stderr

MY_HEAD = "57eefaa0493437c5e4bc95233a91ebb95cf4b63e"
ORIGIN  = None
rc, out, err = run(["git", "rev-parse", "HEAD"])
assert out.decode().strip() == MY_HEAD, f"HEAD moved: {out}"
rc, out, err = run(["git", "rev-parse", "origin/main"])
ORIGIN = out.decode().strip()
assert ORIGIN.startswith("695a88506"), f"origin moved: {ORIGIN}"

# ---- leg 1: pool_core_samples union (blob space LF, dict-only, dedup domain=new lines) ----
rc, ob, err = run(["git", "show", f"{ORIGIN}:results/pool_core_samples.jsonl"])
assert rc == 0, err.decode()
origin_bytes = ob
local_bytes = open("results/pool_core_samples.jsonl", "rb").read()
local_crlf = b"\r\n" in local_bytes
def to_lf(b): return b.replace(b"\r\n", b"\n")
origin_lines = [l for l in to_lf(origin_bytes).split(b"\n") if l]
local_lines  = [l for l in to_lf(local_bytes).split(b"\n") if l]
origin_set = set(origin_lines)
extras = []
seen = set()
for l in local_lines:
    if l in origin_set or l in seen:
        continue
    seen.add(l)
    extras.append(l)
dict_only = []
for l in extras:
    try:
        v = json.loads(l.decode("utf-8"))
    except Exception:
        print(f"WARN non-json local line dropped per dict-only gate: {l[:80]!r}")
        continue
    if isinstance(v, dict):
        dict_only.append(l)
union_lines = origin_lines + dict_only
assert union_lines[:len(origin_lines)] == origin_lines, "origin prefix broken"
for l in union_lines:
    assert isinstance(json.loads(l.decode("utf-8")), dict), "non-dict survived gate"
payload = b"\n".join(union_lines) + b"\n"
if local_crlf:
    payload = payload.replace(b"\n", b"\r\n")
open("results/pool_core_samples.jsonl", "wb").write(payload)
print(f"UNION: origin {len(origin_lines)} + local extras {len(dict_only)} "
      f"(raw extras {len(extras)}, non-dict dropped {len(extras)-len(dict_only)}) = {len(union_lines)}")

# ---- leg 2: CAS update-ref + reset --mixed (r578: never trust checkout after update-ref) ----
rc, out, err = run(["git", "update-ref", "refs/heads/main", ORIGIN, MY_HEAD])
assert rc == 0, err.decode()
rc, out, err = run(["git", "reset", "--mixed", ORIGIN])
assert rc == 0, err.decode()

# ---- leg 3: split checkout ----
PROTECT = {
    "results/pool_core_samples.jsonl",          # union already on disk, rides
    "state.json",                                # origin stale (589), keep MY 590
    "fleet/machines/bm-b.json",                  # origin stale hb, keep MINE
    "logs/iteration-loop/round_reports.md",      # origin dropped my r590 line, keep MINE
}
rc, out, err = run(["git", "diff", "--no-renames", "--name-status", MY_HEAD, ORIGIN])
checkout, deletions = [], []
for line in out.decode().strip().splitlines():
    st, path = line.split("\t")[0], line.split("\t")[-1]
    if st.startswith("D"):
        deletions.append(path)
    elif path not in PROTECT:
        checkout.append(path)
assert not deletions, f"deletion-set non-empty: {deletions}"  # claw family assertion
rc, out, err = run(["git", "checkout", ORIGIN, "--"] + checkout)
assert rc == 0, err.decode()

# ---- leg 4: verify ----
v = json.load(open("state.json", encoding="utf-8"))
assert v["round_no"] == 590, f"state.json regressed: {v['round_no']}"
rr = open("logs/iteration-loop/round_reports.md", encoding="utf-8", errors="replace").read()
assert "round 590 (bm-b)" in rr, "round_reports r590 line missing"
rc, out, err = run(["git", "rev-list", "--count", "HEAD..origin/main"])
assert out.decode().strip() == "0", "behind-origin nonzero"
rc, out, err = run(["git", "status", "--porcelain"])
n_dirty = len(out.decode().strip().splitlines())
print(f"VERIFY: state=590 OK, r590 line OK, behind-origin=0, dirty files={n_dirty}")
print("S0 INTEGRATION COMPLETE (FF + union + 4-face re-land protected)")
